package com.example.approval;
import com.example.approval.adapter.*; import com.example.approval.application.*; import com.example.approval.application.Commands.*; import com.example.approval.domain.*; import java.time.Instant;
public final class Main { private Main(){} public static void main(String[] args){var repository=new InMemoryExpenseRequestRepository();var clock=new FixedClockAdapter(Instant.parse("2026-01-01T10:00:00Z"));var publisher=new RecordingEventPublisher();var notifications=new RecordingNotificationAdapter();var workflow=new ExpenseWorkflow(repository,clock,publisher,notifications);var id=ExpenseRequestId.newId();workflow.create(new CreateExpenseRequest(id,new UserId("employee-1"),new UserId("manager-1"),Money.of("42.50","USD"),"Client travel"));workflow.submit(new SubmitExpenseRequest(id));workflow.approve(new ApproveExpense(id,new UserId("manager-1")));System.out.println("Request "+id.value()+" is "+repository.findById(id).orElseThrow().status()+"; events="+publisher.published().size());} }